'use strict';
/* Admin credential handling — no hardcoded passwords anywhere.
 * Priority: ADMIN_PASSWORD env  >  data/.adminpass (scrypt hash, generated by migrate.js)
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const db = require('./db');

const PF = path.join(db.DATA, '.adminpass');

function readHash() {
  try { return JSON.parse(fs.readFileSync(PF, 'utf8')); } catch (e) { return null; }
}

function setPassword(pw) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(pw, salt, 64).toString('hex');
  // No `bootstrap` flag: an owner-chosen password is a real credential.
  fs.writeFileSync(PF, JSON.stringify({ salt, hash }), { mode: 0o600 });
  try { fs.unlinkSync(path.join(db.DATA, '.adminpass.txt')); } catch (e) {}
  return true;
}

function configured() { return !!process.env.ADMIN_PASSWORD || !!readHash(); }

/** True when the only credential is the auto-generated bootstrap password.
 *  ADMIN_PASSWORD from the environment always counts as a real credential. */
function isBootstrap() {
  if (process.env.ADMIN_PASSWORD) return false;
  const rec = readHash();
  return !!(rec && rec.bootstrap);
}

function verify(pw) {
  const given = String(pw == null ? '' : pw);
  if (!given) return false;

  const env = process.env.ADMIN_PASSWORD;
  if (env) {
    const a = Buffer.from(crypto.createHash('sha256').update(given).digest('hex'));
    const b = Buffer.from(crypto.createHash('sha256').update(String(env)).digest('hex'));
    return crypto.timingSafeEqual(a, b);
  }

  const rec = readHash();
  if (!rec) return false;
  let derived;
  try { derived = crypto.scryptSync(given, rec.salt, 64).toString('hex'); } catch (e) { return false; }
  const a = Buffer.from(derived), b = Buffer.from(rec.hash);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

module.exports = { isBootstrap, verify, setPassword, configured };
